package za.co.lepetse.admin;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.io.*;
import java.math.*;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.zip.*;
import org.apache.pdfbox.Loader;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;

@RestController @RequestMapping("/api/admin")
public class AdminTenderApplications {
 private final JdbcTemplate db;private final TenderRequirementExtractor extractor;private final AdminPricingWorkflow pricing;private final ObjectMapper mapper;
 private static final Set<String> CATEGORIES=Set.of("document","eligibility","briefing","submission","evaluation","other");
 public AdminTenderApplications(JdbcTemplate db,TenderRequirementExtractor extractor,AdminPricingWorkflow pricing,ObjectMapper mapper){this.db=db;this.extractor=extractor;this.pricing=pricing;this.mapper=mapper;}
 private static ResponseStatusException bad(String s){return new ResponseStatusException(HttpStatus.BAD_REQUEST,s);}
 private Map<String,Object> opportunity(long id){var rows=db.queryForList("select * from work_opportunity where id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Opportunity not found.");return rows.getFirst();}
 private static String digest(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}}
 private void dates(Map<String,Object> r){r.replaceAll((k,v)->v instanceof java.sql.Timestamp t?t.toInstant().toString():v instanceof java.sql.Date d?d.toLocalDate().toString():v);}
 private Map<String,Object> file(long id){var rows=db.queryForList("select id,opportunity_id,kind,label,filename,content_type,document_type,expires_on,created_at,pack_included from tender_file where id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found.");var r=rows.getFirst();dates(r);return r;}
 private Map<String,Object> usableFile(long id,long opportunity){var f=file(id);if(f.get("opportunity_id")!=null&&((Number)f.get("opportunity_id")).longValue()!=opportunity)throw bad("Choose a company document or a document for this opportunity.");return f;}
 @GetMapping("/company-documents") List<Map<String,Object>> library(){var rows=db.queryForList("select id,kind,label,filename,content_type,document_type,expires_on,created_at,pack_included from tender_file where kind='company' order by created_at desc,id desc");rows.forEach(this::dates);return rows;}
 @PostMapping(value="/company-documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional(rollbackFor=Exception.class) Map<String,Object> company(@RequestParam MultipartFile file,@RequestParam String label,@RequestParam(defaultValue="other") String documentType,@RequestParam(required=false) java.time.LocalDate expiresOn,Principal actor)throws IOException{return upload(null,"company",label,documentType,expiresOn,file,actor);}
 @PostMapping(value="/opportunities/{id}/application/files",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional(rollbackFor=Exception.class) Map<String,Object> uploadFile(@PathVariable long id,@RequestParam MultipartFile file,@RequestParam String kind,@RequestParam String label,Principal actor)throws IOException{opportunity(id);if(!Set.of("tender","returnable","supporting","proof").contains(kind))throw bad("Choose a valid document purpose.");return upload(id,kind,label,"other",null,file,actor);}
 private Map<String,Object> upload(Long opportunity,String kind,String label,String type,LocalDate expiry,MultipartFile f,Principal actor)throws IOException{
  if(label==null||label.isBlank()||label.length()>200||type.length()>100)throw bad("Add a document name of up to 200 characters.");if(f.isEmpty()||f.getSize()>10*1024*1024)throw bad("Choose a non-empty PDF, PNG or JPEG up to 10 MB.");
  String name=Objects.toString(f.getOriginalFilename(),"document").replace('\\','/');name=name.substring(name.lastIndexOf('/')+1).replaceAll("[\\p{Cntrl}]","");if(name.isBlank()||name.length()>200)throw bad("Check the filename.");byte[] bytes=f.getBytes();String mime;
  if(bytes.length>=5&&new String(bytes,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-")){mime="application/pdf";try(var pdf=Loader.loadPDF(bytes)){if(pdf.isEncrypted()||pdf.getNumberOfPages()>200)throw bad("Use an unencrypted PDF of up to 200 pages.");}catch(IOException e){throw bad("This PDF could not be read.");}}
  else {boolean png=bytes.length>8&&Arrays.equals(Arrays.copyOf(bytes,8),new byte[]{(byte)137,80,78,71,13,10,26,10}),jpeg=bytes.length>3&&bytes[0]==(byte)255&&bytes[1]==(byte)216&&bytes[2]==(byte)255;if(!png&&!jpeg)throw bad("Choose a PDF, PNG or JPEG file.");mime=png?"image/png":"image/jpeg";try(var in=javax.imageio.ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))){var readers=javax.imageio.ImageIO.getImageReaders(in);if(!readers.hasNext())throw bad("This image could not be read.");var reader=readers.next();try{reader.setInput(in);if((long)reader.getWidth(0)*reader.getHeight(0)>25_000_000)throw bad("Use an image smaller than 25 megapixels.");}finally{reader.dispose();}}}
  String ext=name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT);if(!(mime.equals("application/pdf")&&ext.equals("pdf")||mime.equals("image/png")&&ext.equals("png")||mime.equals("image/jpeg")&&Set.of("jpg","jpeg").contains(ext)))throw bad("Use a filename that matches the PDF, PNG or JPEG format.");
  String hash=digest(bytes);var duplicate=db.queryForList("select id from tender_file where opportunity_id is not distinct from ?::bigint and kind=? and sha256=? and label=? and expires_on is not distinct from ?::date",opportunity,kind,hash,label.trim(),expiry==null?null:java.sql.Date.valueOf(expiry));if(!duplicate.isEmpty())return file(((Number)duplicate.getFirst().get("id")).longValue());
  long id=db.queryForObject("insert into tender_file(opportunity_id,kind,label,document_type,filename,content_type,content,sha256,expires_on,uploaded_by) values (?,?,?,?,?,?,?,?,?,?) returning id",Long.class,opportunity,kind,label.trim(),type,name,mime,bytes,hash,expiry==null?null:java.sql.Date.valueOf(expiry),actor.getName());db.update("update tender_file set pack_included=? where id=?",Set.of("returnable","supporting").contains(kind),id);return file(id);
 }
 public record PackSelection(boolean included) {}
 @PostMapping("/opportunities/{id}/application/files/{fileId}/pack") Map<String,Object> selectPack(@PathVariable long id,@PathVariable long fileId,@RequestBody PackSelection s){opportunity(id);var f=usableFile(fileId,id);if(!Set.of("returnable","supporting").contains(f.get("kind")))throw bad("Only completed forms and supporting documents can be added as extra pack files.");db.update("update tender_file set pack_included=? where id=?",s.included(),fileId);return Map.of("saved",true);}
 @GetMapping("/tender-files/{id}/download") ResponseEntity<byte[]> download(@PathVariable long id){var f=file(id);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(f.get("filename").toString(),java.nio.charset.StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").contentType(MediaType.APPLICATION_OCTET_STREAM).body(db.queryForObject("select content from tender_file where id=?",byte[].class,id));}
 @PostMapping("/opportunities/{id}/application/files/{fileId}/extract") Map<String,Object> extract(@PathVariable long id,@PathVariable long fileId)throws IOException{opportunity(id);var f=usableFile(fileId,id);if(!f.get("kind").equals("tender")||!f.get("content_type").equals("application/pdf"))throw bad("Upload a text-based tender PDF first.");try{return Map.of("fileId",fileId,"extraction",extractor.extract(db.queryForObject("select content from tender_file where id=?",byte[].class,fileId)));}catch(IllegalArgumentException e){throw bad(e.getMessage());}catch(IOException e){throw bad("This PDF could not be read. Upload a readable, text-based tender PDF.");}}
 public record Requirement(@NotBlank @Size(max=250) String title,@NotNull @Pattern(regexp="document|eligibility|briefing|submission|evaluation|other") String category,boolean mandatory,@NotNull @Pattern(regexp="todo|done|not_applicable") String status,@NotNull @Size(max=4000) String notes,Long documentId,boolean signatureRequired,boolean signatureConfirmed,Long sourceFileId,@Min(1) @Max(200) Integer sourcePage,@NotNull @Size(max=1400) String sourceExcerpt,@Min(1) Integer version) {}
 public record Reviewed(@AssertTrue boolean reviewed,@NotEmpty @Size(max=80) List<@Valid Requirement> requirements) {}
 @PostMapping("/opportunities/{id}/application/requirements") @Transactional Map<String,Object> add(@PathVariable long id,@Valid @RequestBody Reviewed body,Principal actor){opportunity(id);int added=0;for(var r:body.requirements()){validate(r,id);String sourceKey=r.sourceFileId()==null?null:digest((r.sourceFileId()+"|"+r.sourcePage()+"|"+r.sourceExcerpt()).getBytes(java.nio.charset.StandardCharsets.UTF_8));added+=db.update("insert into tender_requirement(opportunity_id,title,category,mandatory,status,notes,document_id,signature_required,signature_confirmed,source_file_id,source_page,source_excerpt,source_key,updated_by) values (?,?,?,?,?,?,?,?,?,?,?,?,?,?) on conflict(opportunity_id,source_key) do nothing",id,r.title().trim(),r.category(),r.mandatory(),r.status(),r.notes(),r.documentId(),r.signatureRequired(),r.signatureConfirmed(),r.sourceFileId(),r.sourcePage(),r.sourceExcerpt(),sourceKey,actor.getName());}return Map.of("added",added);}
 @PostMapping("/opportunities/{id}/application/requirements/{requirement}") @Transactional Map<String,Object> update(@PathVariable long id,@PathVariable long requirement,@Valid @RequestBody Requirement r,Principal actor){opportunity(id);validate(r,id);int changed=db.update("update tender_requirement set title=?,category=?,mandatory=?,status=?,notes=?,document_id=?,signature_required=?,signature_confirmed=?,version=version+1,updated_at=now(),updated_by=? where opportunity_id=? and id=? and version=?",r.title().trim(),r.category(),r.mandatory(),r.status(),r.notes(),r.documentId(),r.signatureRequired(),r.signatureConfirmed(),actor.getName(),id,requirement,r.version());if(changed==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This requirement changed. Reload before saving.");return Map.of("saved",true);}
 private void validate(Requirement r,long id){if(r.documentId()!=null)usableFile(r.documentId(),id);if(r.sourceFileId()!=null){var source=usableFile(r.sourceFileId(),id);if(!source.get("kind").equals("tender")||r.sourcePage()==null)throw bad("Check the source PDF and page reference.");}if(r.status().equals("not_applicable")&&r.notes().isBlank())throw bad("Explain why this requirement is not applicable.");if(r.status().equals("done")){if(r.signatureRequired()&&!r.signatureConfirmed())throw bad("Confirm the required signature before marking this requirement complete.");}}
 private List<Map<String,Object>> quote(Map<String,Object> o){if(o.get("rfq_id")==null)return List.of();return db.queryForList("select q.id,q.reference,q.valid_until from quotation q join rfq_pricing_work w on w.rfq_id=q.rfq_id where q.rfq_id=? and q.status in ('draft','issued') and q.approval_version=w.approval_version and q.draft_version=w.quote_version order by q.revision desc limit 1",o.get("rfq_id"));}
 @GetMapping("/opportunities/{id}/application") @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) Map<String,Object> get(@PathVariable long id){var o=opportunity(id);var reqs=db.queryForList("select r.*,f.label document_label,f.expires_on from tender_requirement r left join tender_file f on f.id=r.document_id where r.opportunity_id=? order by r.id",id);reqs.forEach(this::dates);var files=db.queryForList("select id,kind,label,filename,content_type,document_type,expires_on,created_at,pack_included from tender_file where opportunity_id=? order by id",id);files.forEach(this::dates);var missing=new ArrayList<String>();LocalDate today=LocalDate.now(ZoneId.of("Africa/Johannesburg"));if(reqs.isEmpty())missing.add("Review the tender and add its requirements");for(var r:reqs){if(!Boolean.TRUE.equals(r.get("mandatory")))continue;boolean done=r.get("status").equals("done"),na=r.get("status").equals("not_applicable");if(!done&&!na)missing.add(r.get("title").toString());if(done&&r.get("expires_on")!=null&&LocalDate.parse(r.get("expires_on").toString()).isBefore(today))missing.add("Expired document: "+r.get("document_label"));if(done&&Boolean.TRUE.equals(r.get("signature_required"))&&!Boolean.TRUE.equals(r.get("signature_confirmed")))missing.add("Signature outstanding: "+r.get("title"));}
 var quotes=quote(o);if(quotes.isEmpty())missing.add("Finalise a current customer quotation in the linked request");else if(((java.sql.Date)quotes.getFirst().get("valid_until")).toLocalDate().isBefore(today))missing.add("Customer quotation has expired");
 try{var d=mapper.readTree(o.get("details").toString());if(OffsetDateTime.parse(d.path("closing").asText()).toInstant().isBefore(Instant.now()))missing.add("Tender closing deadline has passed");}catch(Exception e){missing.add("Confirm the tender closing deadline");}
 var submissions=db.queryForList("select s.*,f.filename proof_filename from tender_submission s left join tender_file f on f.id=s.proof_file_id where s.opportunity_id=? order by s.id desc",id);submissions.forEach(this::dates);quotes.forEach(this::dates);var checks=new ArrayList<Map<String,Object>>();checks.add(Map.of("key","requirements","title","Capture the tender requirements","complete",!reqs.isEmpty(),"detail",reqs.isEmpty()?"Review the tender PDF and add the required documents and tasks.":reqs.size()+" requirements recorded."));boolean quoteReady=!quotes.isEmpty()&&!LocalDate.parse(quotes.getFirst().get("valid_until").toString()).isBefore(today);checks.add(Map.of("key","quotation","title","Finalise customer quotation","complete",quoteReady,"detail",quotes.isEmpty()?"Source the products, approve prices and finalise the customer quote.":quoteReady?quotes.getFirst().get("reference").toString():"The quotation has expired."));boolean open=!missing.contains("Tender closing deadline has passed")&&!missing.contains("Confirm the tender closing deadline");checks.add(Map.of("key","deadline","title","Tender is still open","complete",open,"detail",open?"Check the official closing date and submission instructions before sending.":"Confirm an official extension before continuing."));return Map.of("requirements",reqs,"files",files,"companyDocuments",library(),"missing",missing,"ready",missing.isEmpty(),"quotations",quotes,"submissions",submissions,"checks",checks,"rfqId",o.get("rfq_id")==null?0:o.get("rfq_id"));
 }
 @GetMapping("/opportunities/{id}/application/pack") @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) ResponseEntity<byte[]> pack(@PathVariable long id)throws IOException{var o=opportunity(id);var state=get(id);var chosen=db.queryForList("select distinct f.id,f.filename,f.content from tender_file f where (f.opportunity_id=? and f.kind in ('returnable','supporting') and f.pack_included) or f.id in (select document_id from tender_requirement where opportunity_id=? and status<>'not_applicable') order by f.id",id,id);long total=chosen.stream().mapToLong(f->((byte[])f.get("content")).length).sum();if(total>50*1024*1024)throw bad("The selected documents exceed the 50 MB pack limit.");var out=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(out)){StringBuilder summary=new StringBuilder("LEPETSE - APPLICATION REVIEW\nOpportunity "+o.get("reference")+"\n"+(Boolean.TRUE.equals(state.get("ready"))?"Checklist complete - verify the final pack against the official tender.\n":"DRAFT PACK - requirements outstanding; do not treat as submission-ready.\n"));for(Object m:(List<?>)state.get("missing"))summary.append("Outstanding: ").append(m).append('\n');for(var r:db.queryForList("select title,status,notes from tender_requirement where opportunity_id=? order by id",id))summary.append(r.get("status")).append(": ").append(r.get("title")).append(" - ").append(r.get("notes")).append('\n');summary.append("File names have numeric prefixes to avoid collisions. Check required submission filenames, signatures, portal instructions and size limits before uploading. This pack does not submit the tender.\n");entry(zip,"Application-checklist.txt",summary.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));var quotes=quote(o);if(!quotes.isEmpty()){long q=((Number)quotes.getFirst().get("id")).longValue(),rfq=((Number)o.get("rfq_id")).longValue();entry(zip,"Quotation-"+quotes.getFirst().get("reference")+".pdf",CustomerQuotationPdf.render(pricing.preview(rfq,q)));}for(var f:chosen)entry(zip,"documents/"+f.get("id")+"-"+f.get("filename").toString().replaceAll("[^A-Za-z0-9._ -]","_"),(byte[])f.get("content"));}return ResponseEntity.ok().contentType(MediaType.parseMediaType("application/zip")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\"Lepetse-application-"+id+".zip\"").header("X-Content-Type-Options","nosniff").body(out.toByteArray());}
 private void entry(ZipOutputStream zip,String name,byte[] bytes)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(bytes);zip.closeEntry();}
 public record Submission(@NotNull UUID submissionKey,@NotNull OffsetDateTime submittedAt,@NotBlank @Size(max=100) String channel,@NotBlank @Size(max=500) String recipient,@NotNull @Size(max=1000) String confirmation,Long proofFileId,@AssertTrue boolean confirmed) {}
 @PostMapping("/opportunities/{id}/application/submissions") @Transactional Map<String,Object> submitted(@PathVariable long id,@Valid @RequestBody Submission s,Principal actor){opportunity(id);if(s.submittedAt().toInstant().isAfter(Instant.now().plusSeconds(60)))throw bad("Record a submission that has already happened.");if(s.proofFileId()!=null){var f=usableFile(s.proofFileId(),id);if(!f.get("kind").equals("proof"))throw bad("Choose a proof-of-submission file for this opportunity.");}db.queryForList("select pg_advisory_xact_lock(hashtextextended(?,0))",s.submissionKey().toString());var existing=db.queryForList("select * from tender_submission where submission_key=?",s.submissionKey());if(!existing.isEmpty()){var r=existing.getFirst();if(((Number)r.get("opportunity_id")).longValue()!=id||!r.get("recipient").equals(s.recipient().trim())||!r.get("channel").equals(s.channel())||!r.get("confirmation").equals(s.confirmation())||!Objects.equals(r.get("proof_file_id"),s.proofFileId())||!((java.sql.Timestamp)r.get("submitted_at")).toInstant().equals(s.submittedAt().toInstant().truncatedTo(java.time.temporal.ChronoUnit.MICROS)))throw new ResponseStatusException(HttpStatus.CONFLICT,"This submission record changed. Use a new record.");return Map.of("recorded",true);}db.update("insert into tender_submission(opportunity_id,submitted_at,channel,recipient,confirmation,proof_file_id,recorded_by,submission_key) values (?,?,?,?,?,?,?,?)",id,java.sql.Timestamp.from(s.submittedAt().toInstant()),s.channel(),s.recipient().trim(),s.confirmation(),s.proofFileId(),actor.getName(),s.submissionKey());db.update("update work_opportunity set progress='submitted',version=version+1,updated_at=now() where id=?",id);return Map.of("recorded",true);}
}
